(()=>{
const arena=document.querySelector('.arena'),shot=document.getElementById('shot'),input=document.getElementById('typeInput'),actors=document.querySelectorAll('.battle-characters .mini');
const impact=document.createElement('div');impact.id='impact';arena.append(impact);
const count=document.createElement('div');count.id='countdownOverlay';count.className='hidden';count.innerHTML='<span>STARTS IN</span><strong id="countdownValue">3</strong>';arena.append(count);
const victory=document.createElement('div');victory.id='victoryOverlay';victory.className='hidden';victory.setAttribute('role','dialog');victory.setAttribute('aria-modal','true');victory.innerHTML='<div class="victory-panel"><div style="font-size:52px">🏆</div><h2 id="victoryTitle">YOU WIN!</h2><p id="victoryText">First to three kills!</p><div class="row" style="justify-content:center"><button class="primary" id="againButton">PLAY AGAIN</button><button class="secondary" id="exitButton">EXIT</button></div></div>';document.body.append(victory);
const originalStart=startGame,originalRound=newRound,originalWin=win,originalEnd=endGame;
let countTimer=null,shotTimers=[],busyTimer=null;
function clearEffects(){clearInterval(countTimer);countTimer=null;shotTimers.forEach(clearTimeout);shotTimers=[];clearTimeout(busyTimer);count.classList.add('hidden');arena.classList.remove('shake');shot.classList.remove('animate','enemyShot');impact.classList.remove('pop');actors.forEach(a=>a.classList.remove('attacking','hurt','typing'))}
function closeVictory(){victory.classList.add('hidden');victory.querySelectorAll('.confetti').forEach(e=>e.remove())}
function gameStart(){roundActive=true;input.disabled=false;input.focus();let interval=60000/(Number(document.getElementById('botWpm').textContent)*5);botTimer=setInterval(()=>{if(!roundActive)return;botProgress++;document.getElementById('botInput').value=word.slice(0,botProgress);actors[1].classList.add('typing');if(botProgress>=word.length)win('bot')},interval)}
startGame=function(level){clearEffects();closeVictory();originalStart(level)};
newRound=function(){clearEffects();originalRound();if(roundIndex===1){clearInterval(botTimer);botTimer=null;roundActive=false;input.disabled=true;let remaining=3;count.classList.remove('hidden');document.getElementById('countdownValue').textContent=remaining;beep(360);countTimer=setInterval(()=>{remaining--;if(remaining>0){document.getElementById('countdownValue').textContent=remaining;beep(360)}else{clearInterval(countTimer);countTimer=null;count.classList.add('hidden');beep(760);gameStart()}},1000)}};
win=function(who){if(!roundActive)return;roundActive=false;stopTimers();input.disabled=true;actors.forEach(a=>a.classList.remove('typing'));let player=who==='player',a=actors[player?0:1],v=actors[player?1:0];if(player){p++;document.getElementById('pScore').textContent=p}else{b++;document.getElementById('bScore').textContent=b}document.getElementById('result').textContent=player?'Great shot! You typed first.':'Bot hit! Type faster next time.';a.classList.add('attacking');shot.classList.toggle('enemyShot',!player);shot.classList.remove('animate');void shot.offsetWidth;shot.classList.add('animate');beep(player?660:280);
shotTimers.push(setTimeout(()=>{v.classList.add('hurt');arena.classList.add('shake');impact.style.left=player?'70%':'22%';impact.classList.remove('pop');void impact.offsetWidth;impact.classList.add('pop');beep(130)},420));
shotTimers.push(setTimeout(()=>{actors.forEach(x=>x.classList.remove('attacking','hurt'));arena.classList.remove('shake');if(p>=3||b>=3){victory.classList.remove('hidden');document.getElementById('victoryTitle').textContent=p>=3?'YOU WIN!':'BOT WINS!';document.getElementById('victoryText').textContent=p>=3?'Amazing typing! You got 3 kills.':'Bot got 3 kills. Try again?';if(p>=3){for(let i=0;i<75;i++){let el=document.createElement('span');el.className='confetti';el.style.left=Math.random()*100+'vw';el.style.background=['#3176bd','#d86893','#efd076','#59b8a0'][i%4];el.style.animationDuration=(2+Math.random()*2)+'s';el.style.animationDelay=Math.random()*.7+'s';victory.append(el)}[710,860,1000].forEach((f,i)=>setTimeout(()=>beep(f),i*180))}else beep(170)}else nextTimer=setTimeout(()=>newRound(),580)},1100))};
endGame=function(){clearEffects();closeVictory();originalEnd()};
input.addEventListener('input',()=>{if(roundActive){actors[0].classList.add('typing');clearTimeout(busyTimer);busyTimer=setTimeout(()=>actors[0].classList.remove('typing'),550)}});
document.getElementById('againButton').onclick=()=>{closeVictory();startGame(difficulty)};
document.getElementById('exitButton').onclick=()=>{closeVictory();endGame();show('modes')};
})();